const defaults=[{code:'3',name:'Religação',urban:13325,rural:40642},{code:'5',name:'Corte simbólico',urban:7662,rural:39309},{code:'383',name:'Corte no ramal',urban:22653,rural:41308},{code:'236',name:'Negociação',urban:21320,rural:39976}];
const key='osfacil-v1';
let state;try{state=JSON.parse(localStorage.getItem(key))}catch{}
if(!state||typeof state!=='object'||Array.isArray(state))state={};
const validRate=r=>r&&typeof r.code==='string'&&/^[A-Za-z0-9_-]{1,20}$/.test(r.code)&&typeof r.name==='string'&&r.name.trim()&&Number.isSafeInteger(r.urban)&&r.urban>=0&&Number.isSafeInteger(r.rural)&&r.rural>=0;
if(!Array.isArray(state.rates))state.rates=structuredClone(defaults);
state.rates=state.rates.filter((r,i,a)=>validRate(r)&&a.findIndex(x=>x?.code===r.code)===i);
if(!state.days||typeof state.days!=='object'||Array.isArray(state.days))state.days={};
for(const d of Object.keys(state.days)){
 if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||!Array.isArray(state.days[d])){delete state.days[d];continue}
 state.days[d]=state.days[d].filter(e=>e&&typeof e.code==='string'&&['urban','rural'].includes(e.area)&&Number.isSafeInteger(e.price)&&e.price>=0).map(e=>({...e,name:typeof e.name==='string'?e.name:state.rates.find(r=>r.code===e.code)?.name||`Serviço ${e.code}`}));
}
state.settings={...state.settings,includeReportValues:state.settings?.includeReportValues!==false};
let page='today',area='urban';
const localDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
let date=localDate(),month=date.slice(0,7);
const money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const dayLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const entries=d=>state.days[d]||[],sum=a=>a.reduce((n,e)=>n+e.price,0),count=code=>entries(date).filter(e=>e.code===code&&e.area===area).length;
const activeRates=()=>state.rates.filter(r=>r.active!==false);
function groupEntries(es){const map=new Map();for(const e of es){const k=JSON.stringify([e.code,e.name,e.area]);if(!map.has(k))map.set(k,{code:e.code,name:e.name,area:e.area,quantity:0,total:0});const r=map.get(k);r.quantity++;r.total+=e.price}return [...map.values()]}
function notify(s){const t=document.getElementById('toast');t.textContent=s;t.hidden=false;clearTimeout(window.timer);window.timer=setTimeout(()=>t.hidden=true,3500)}
function save(){try{localStorage.setItem(key,JSON.stringify(state));return true}catch{notify('Não foi possível salvar. Libere espaço e tente novamente.');return false}}
function change(code,delta){const before=JSON.stringify(state);const a=state.days[date]||(state.days[date]=[]),r=state.rates.find(r=>r.code===code);if(delta>0){if(!r||r.active===false)return;a.push({code,name:r.name,area,price:r[area],at:new Date().toISOString()})}else{const i=a.findLastIndex(e=>e.code===code&&e.area===area);if(i>=0)a.splice(i,1)}if(!a.length)delete state.days[date];if(!save())state=JSON.parse(before);render()}
function report(d){const show=state.settings.includeReportValues;return `OS Fácil • ${dayLabel(d)}\n${state.profile?.name||''}\n\n`+groupEntries(entries(d)).map(r=>`${r.code} • ${r.name} • ${r.area==='urban'?'Urbano':'Rural'}: ${r.quantity} OS${show?' / '+money(r.total):''}`).join('\n')+`\n\nTotal: ${entries(d).length} OS${show?' • '+money(sum(entries(d))):''}`}
async function share(){if(window.OSReport)await OSReport.open(date);else notify('O relatório não carregou. Atualize o aplicativo e tente novamente.')}
function parsePrice(value){const s=String(value).trim();return /^\d{1,7}([,.]\d{1,2})?$/.test(s)?Math.round(Number(s.replace(',','.'))*100):null}
function render(){
 document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const app=document.getElementById('app');
 if(page==='today'){
  const es=entries(date),visible=state.rates.filter(r=>r.active!==false||es.some(e=>e.code===r.code&&e.area===area));
  app.innerHTML=`<div class="date"><div><h2>Meu dia</h2><small>Uma OS de cada vez.</small></div><input aria-label="Data dos serviços" id="date" type="date" value="${date}"></div><section class="hero"><small class="eyebrow">Total do dia</small><div class="money" data-cents="${sum(es)}">${money(sum(es))}</div><small>Seu resultado em serviços realizados</small><footer><span id="daily-count"><b>${es.length}</b> OS registradas</span><span>Salvo no aparelho ✓</span></footer></section><div class="tabs" aria-label="Área"><button data-area="urban" class="${area==='urban'?'active':''}">⌂ &nbsp; Urbano</button><button data-area="rural" class="${area==='rural'?'active':''}">♧ &nbsp; Rural</button></div><div class="section-head"><h2>Registrar serviço</h2><small>Toque em + ao concluir uma OS.</small></div>${visible.map(r=>`<article class="card"><div class="row"><div><span class="code">OS ${esc(r.code)}${r.active===false?' · TARIFA REMOVIDA':''}</span><div class="name">${esc(r.name)}</div><div class="price">${money(r[area])} por serviço</div></div><span class="chip">${area==='urban'?'Urbano':'Rural'}</span></div><div class="controls"><button data-code="${esc(r.code)}" data-delta="-1" aria-label="Remover ${esc(r.name)}" ${count(r.code)?'':'disabled'}>−</button><span class="count">${count(r.code)}</span><button class="plus" data-code="${esc(r.code)}" data-delta="1" aria-label="Adicionar ${esc(r.name)}" ${r.active===false?'disabled':''}>+</button><span class="subtotal" data-cents="${sum(es.filter(e=>e.code===r.code&&e.area===area))}">${money(sum(es.filter(e=>e.code===r.code&&e.area===area)))}</span></div></article>`).join('')||'<p class="empty">Nenhuma tarifa ativa. Adicione um serviço no menu Tarifas.</p>'}<button class="full" id="share">Compartilhar diária em imagem ↗</button><p class="note">O botão − remove o último registro desse serviço na área selecionada.</p>`;
  document.getElementById('date').onchange=e=>{if(e.target.value){date=e.target.value;render()}};
  app.querySelectorAll('[data-area]').forEach(b=>b.onclick=()=>{area=b.dataset.area;render()});
  app.querySelectorAll('[data-code]').forEach(b=>b.onclick=()=>change(b.dataset.code,Number(b.dataset.delta)));
  document.getElementById('share').onclick=share;
 }
 if(page==='history'){
  const ds=Object.keys(state.days).filter(d=>d.startsWith(month)&&entries(d).length).sort().reverse(),all=ds.flatMap(entries);
  app.innerHTML=`<div class="date"><h2>Histórico</h2><input id="month" aria-label="Mês do histórico" type="month" value="${month}"></div><section class="hero"><small class="eyebrow">Resultado do mês</small><div class="money">${money(sum(all))}</div><small>${all.length} OS em ${ds.length} dias trabalhados</small></section>${ds.length?ds.map(d=>`<article class="card"><div class="row"><button class="historydate" data-day="${d}">${dayLabel(d)} ↗</button><b>${money(sum(entries(d)))}</b></div><small>${entries(d).length} serviços realizados</small>${groupEntries(entries(d)).map(r=>`<div class="row historyline"><span>${esc(r.name)} · ${r.area==='urban'?'Urbano':'Rural'} · ${r.quantity}</span><span>${money(r.total)}</span></div>`).join('')}</article>`).join(''):'<div class="empty">Nenhuma OS neste mês.<p>Seus registros aparecerão aqui.</p></div>'}<p class="note">Toque em uma data para consultar, corrigir ou compartilhar os registros.</p>`;
  document.getElementById('month').onchange=e=>{if(e.target.value){month=e.target.value;render()}};
  app.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{date=b.dataset.day;page='today';render()});
 }
 if(page==='rates')renderRates(app);
}
function renderRates(app){
 app.innerHTML=`<div class="date"><h2>Tarifas dos serviços</h2><button class="chip" id="add-rate">+ Nova tarifa</button></div><p class="muted">Os valores antigos e os serviços de tarifas removidas continuam no histórico.</p><section class="card"><label class="setting-toggle" for="report-values"><span><strong>Valores no relatório</strong><small>Incluir preços e total em reais na imagem compartilhada.</small></span><input id="report-values" type="checkbox" role="switch" ${state.settings.includeReportValues?'checked':''}></label></section><form id="rates">${activeRates().map(r=>`<section class="card"><div class="row"><div><span class="code">OS ${esc(r.code)}</span><div class="name">${esc(r.name)}</div></div><button type="button" class="remove-rate" data-remove="${esc(r.code)}" aria-label="Remover tarifa ${esc(r.name)}">Remover</button></div><div class="rategrid">${['urban','rural'].map(a=>`<label>${a==='urban'?'Urbano':'Rural'} · R$<input required inputmode="decimal" name="${esc(r.code)}-${a}" value="${(r[a]/100).toFixed(2).replace('.',',')}" aria-label="${esc(r.name)} ${a==='urban'?'urbano':'rural'}"></label>`).join('')}</div></section>`).join('')||'<p class="empty">Você ainda não tem tarifas ativas.</p>'}${activeRates().length?'<button class="full">Salvar tarifas</button>':''}</form><p class="note">Os dados ficam neste aparelho. Compartilhe as diárias para guardar cópias.</p>`;
 document.getElementById('add-rate').onclick=()=>{const f=document.getElementById('new-rate-form');f.reset();document.getElementById('new-rate-error').textContent='';document.getElementById('new-rate-dialog').showModal()};
 document.getElementById('report-values').onchange=e=>{const old=state.settings.includeReportValues;state.settings.includeReportValues=e.target.checked;if(!save()){state.settings.includeReportValues=old;e.target.checked=old}else notify(e.target.checked?'Relatório com valores.':'Relatório sem valores.')};
 app.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const r=state.rates.find(r=>r.code===b.dataset.remove);const dialog=document.getElementById('remove-rate-dialog');dialog.dataset.code=r.code;document.getElementById('remove-rate-name').textContent=r.name;dialog.showModal()});
 document.getElementById('rates').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),rates=structuredClone(state.rates);for(const r of rates.filter(r=>r.active!==false))for(const a of ['urban','rural']){const n=parsePrice(data.get(`${r.code}-${a}`));if(n===null){notify('Informe valores válidos, como 133,25.');return}r[a]=n}const old=state.rates;state.rates=rates;if(save())notify('Tarifas atualizadas!');else state.rates=old};
}
function setupRateDialogs(){
 document.getElementById('new-rate-form').onsubmit=e=>{e.preventDefault();const f=e.target,code=f.elements.code.value.trim(),name=f.elements.service.value.trim().replace(/\s+/g,' '),urban=parsePrice(f.elements.urban.value),rural=parsePrice(f.elements.rural.value),error=document.getElementById('new-rate-error');if(!/^[A-Za-z0-9_-]{1,20}$/.test(code)||!name||name.length>60||urban===null||rural===null){error.textContent='Preencha código, nome e os dois valores. Use números como 133,25.';return}const existing=state.rates.find(r=>r.code===code);if(existing&&existing.active!==false){error.textContent='Já existe uma tarifa ativa com esse código.';return}const old=structuredClone(state.rates);if(existing)Object.assign(existing,{name,urban,rural,active:true});else state.rates.push({code,name,urban,rural,active:true});if(save()){document.getElementById('new-rate-dialog').close();render();notify('Tarifa adicionada!')}else state.rates=old};
 document.getElementById('confirm-remove-rate').onclick=()=>{const dialog=document.getElementById('remove-rate-dialog'),r=state.rates.find(r=>r.code===dialog.dataset.code);if(!r)return;const old=r.active;r.active=false;if(save()){dialog.close();render();notify('Tarifa removida. Histórico preservado.')}else r.active=old};
 document.querySelectorAll('[data-close-dialog]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.closeDialog).close());
}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();window.scrollTo(0,0)});setupRateDialogs();render();
